const ledgerDrift = `-- name: LedgerDrift :many
SELECT a.id, a.number, a.status, a.cost, a.accum_depr, a.dep_months_done,
       COALESCE(SUM(e.cost_delta), 0)::numeric(18,3) AS ledger_cost, COALESCE(SUM(e.accum_delta), 0)::numeric(18,3) AS ledger_accum, COALESCE(SUM(e.months_delta), 0)::int AS ledger_months
  FROM fa_assets a
  LEFT JOIN fa_ledger e ON e.property_id = a.property_id AND e.asset_id = a.id
 WHERE a.tenant_id = $1 AND a.property_id = $2 AND a.status IN ('ACTIVE', 'CANCELLED')
 GROUP BY a.id
HAVING CASE WHEN a.status = 'ACTIVE' THEN (a.cost <> COALESCE(SUM(e.cost_delta), 0) OR a.accum_depr <> COALESCE(SUM(e.accum_delta), 0) OR a.dep_months_done <> COALESCE(SUM(e.months_delta), 0))
            ELSE (COALESCE(SUM(e.cost_delta), 0) <> 0 OR COALESCE(SUM(e.accum_delta), 0) <> 0 OR COALESCE(SUM(e.months_delta), 0) <> 0) END
 ORDER BY a.number
`

type LedgerDriftParams struct {
	TenantID   int64
	PropertyID int64
}

type LedgerDriftRow struct {
	ID            int64
	Number        string
	Status        string
	Cost          decimal.Decimal
	AccumDepr     decimal.Decimal
	DepMonthsDone int32
	LedgerCost    decimal.Decimal
	LedgerAccum   decimal.Decimal
	LedgerMonths  int32
}

// Assets whose state differs from the sum of their ledger rows (active assets; a cancelled one must net to zero).
func (q *Queries) LedgerDrift(ctx context.Context, arg LedgerDriftParams) ([]LedgerDriftRow, error) {
	rows, err := q.db.Query(ctx, ledgerDrift, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LedgerDriftRow{}
	for rows.Next() {
		var i LedgerDriftRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.Status,
			&i.Cost,
			&i.AccumDepr,
			&i.DepMonthsDone,
			&i.LedgerCost,
			&i.LedgerAccum,
			&i.LedgerMonths,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

